mapper.select:
select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.avatar, u.phonenumber, u.sex, u.status,
       case when ut.user_id is not null then 1 else 0 end as team_member
from sys_user u
left join sys_user_project up on u.user_id = up.user_id
    and up.project_lock != 1 and up.project_id = #{projectId}
left join sys_project p on p.project_id = #{projectId}
left join sys_user_team ut on ut.user_id = u.user_id
    and ut.team_id = p.team_id and ut.team_lock != 1

order by team_member desc, u.user_id
limit #{limit} offset #{offset}

mapper.update:
update sys_user_project
project_lock = #{projectLock}, collect = #{collect},
where user_id = #{userId} and project_id = #{projectId}

mapper.select:
select user_project_id, user_id, project_id, collect, project_lock
from sys_user_project

    and user_id = #{userId}
    and project_id = #{projectId}
